-- catalog-override: DuckDB's SQLGlot dialect writer wraps modulo divisors in NULLIF; preserve exact deterministic score buckets.
UPDATE {table_relation} SET tier = CASE WHEN tier IS NULL THEN NULL ELSE CAST(((CAST(tier AS INTEGER) + 1) % 100) AS TINYINT) END WHERE abs(((coalesce(customerid, 0) % 1000000) * 2654435761 + {batch_offset}) % 1000000) >= {start} AND abs(((coalesce(customerid, 0) % 1000000) * 2654435761 + {batch_offset}) % 1000000) < {end};
